-- Privileged authorized executor only; no grant widening. All writes roll back.
BEGIN;
DO $$
DECLARE s jsonb; t jsonb; rid uuid; ctx jsonb; cmd uuid:=gen_random_uuid(); version integer; result jsonb; ch text; before_rows text;
BEGIN
 s:=jsonb_build_object('reservation',jsonb_build_object('id','qa','alumno_id','qa','currency','ARS'), 'payments','[{"status":"validado","currency":"ARS","amount":100000},{"status":"anulado","currency":"ARS","amount":999999},{"status":"rechazado","currency":"ARS","amount":100}]'::jsonb,'refunds','[{"moneda":"ARS","monto":10000}]'::jsonb,'directs','[]'::jsonb,'transfers','[]'::jsonb,'credits','[]'::jsonb,'adjustments','[]'::jsonb,'imputations','[]'::jsonb);
 t:=public._rescheduling_settlement_totals(s);
 IF (t->>'net_ars')::numeric<>90000 OR (t->>'excluded_count')::integer<>2 OR (t->>'blocked')::boolean THEN RAISE EXCEPTION 'ARS 100%% net/exclusions failed'; END IF;
 t:=public._rescheduling_settlement_totals(s||'{"directs":[{"status":"confirmed","currency":"ARS","amount":840000,"replacement_reservation_id":"qa"}]}'::jsonb);
 IF (t->>'net_ars')::numeric<>90000 OR (t->>'direct_paid_ars')::numeric<>840000 OR NOT (t->>'blocked')::boolean THEN RAISE EXCEPTION 'Third party cash separation failed'; END IF;
 t:=public._rescheduling_settlement_totals(s||'{"payments":[{"status":"validado","currency":"EUR","amount":100000}]}'::jsonb);
 IF (t->>'paid_ars')::numeric<>0 OR NOT (t->>'blocked')::boolean THEN RAISE EXCEPTION 'Multicurrency failed'; END IF;
 t:=public._rescheduling_settlement_totals(s||'{"payments":[{"status":"validado","currency":"ARS","amount":100000,"payment_reference":"same"},{"status":"validado","currency":"ARS","amount":100000,"payment_reference":"same"}]}'::jsonb);
 IF NOT (t->>'blocked')::boolean OR (t->>'paid_ars')::numeric<>100000 THEN RAISE EXCEPTION 'Duplicate receipt counted or allowed'; END IF;
 t:=public._rescheduling_settlement_totals(s||'{"refunds":[{"moneda":"ARS","monto":100001}]}'::jsonb);
 IF NOT (t->>'blocked')::boolean THEN RAISE EXCEPTION 'Overrefund allowed'; END IF;
 PERFORM set_config('request.jwt.claims','{}',true);
 BEGIN PERFORM public.admin_rescheduling_settlement_preview(gen_random_uuid()); RAISE EXCEPTION 'Anonymous allowed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Acceso no autorizado' THEN RAISE; END IF; END;
 PERFORM set_config('request.jwt.claims','{"sub":"0d70cac6-b7ff-4041-a90e-d40614f39622","role":"authenticated"}',true);
 SELECT r.id INTO rid FROM public.event_reservations r WHERE event_id='67b4e85d-b00b-4b74-9644-99458d948c65' AND reservation_status NOT IN ('cancelada','rechazada','cancelled','cancelado') AND NOT (public._rescheduling_settlement_totals(public._rescheduling_settlement_sources(r.id))->>'blocked')::boolean AND (public._rescheduling_settlement_totals(public._rescheduling_settlement_sources(r.id))->>'net_ars')::numeric>=50000 ORDER BY r.id LIMIT 1;
 IF rid IS NULL THEN RAISE EXCEPTION 'No safe real reservation for QA'; END IF;
 SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY id)::text) INTO before_rows FROM public.event_reservations r;
 SELECT coalesce(revision,0) INTO version FROM public.reservation_rescheduling_requests WHERE reservation_id=rid;
 PERFORM public.submit_rescheduling_request('67b4e85d-b00b-4b74-9644-99458d948c65',rid,'{"choice":"refund","consent":true,"source":"QA reversible","note":"QA sin ejecución","jersey_requested":false}',coalesce(version,0),gen_random_uuid());
 ctx:=public.admin_rescheduling_settlement_preview(rid); version:=coalesce((ctx->'proposal'->>'version')::integer,0);
 result:=public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,cmd,jsonb_build_object('state','validated','note','QA reversible','authorized_amount',(ctx->'totals'->>'net_ars')::numeric,'checks',jsonb_build_object('reconciled',true)));
 IF (result->'proposal'->>'authorized_amount')::numeric<>(ctx->'totals'->>'net_ars')::numeric OR (result->'proposal'->>'jersey_amount')::numeric<>0 THEN RAISE EXCEPTION 'Validated no jersey failed'; END IF;
 PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,cmd,jsonb_build_object('state','validated','note','QA reversible','authorized_amount',(ctx->'totals'->>'net_ars')::numeric,'checks',jsonb_build_object('reconciled',true)));
 IF (SELECT count(*) FROM public.rescheduling_settlement_proposals WHERE command_id=cmd)<>1 THEN RAISE EXCEPTION 'Double click duplicated'; END IF;
 BEGIN PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,gen_random_uuid(),'{"state":"estimated","note":"stale version"}');RAISE EXCEPTION 'Concurrent version allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Otra propuesta fue guardada. Recargá' THEN RAISE;END IF;END;
 BEGIN PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,cmd,'{"state":"estimated","note":"different"}');RAISE EXCEPTION 'Collision allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Identificador utilizado para otra operación' THEN RAISE;END IF;END;
 version:=version+1;
 BEGIN PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,gen_random_uuid(),jsonb_build_object('state','validated','note','too much','authorized_amount',(ctx->'totals'->>'net_ars')::numeric+1,'checks',jsonb_build_object('reconciled',true))); RAISE EXCEPTION 'Overauthorization allowed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Monto fuera del neto real confirmado' THEN RAISE;END IF;END;
 SELECT revision INTO version FROM public.reservation_rescheduling_requests WHERE reservation_id=rid;
 SELECT value->>'value' INTO ch FROM jsonb_array_elements(public._rescheduling_size(rid)->'options') LIMIT 1;
 IF ch IS NULL THEN RAISE EXCEPTION 'Missing jersey options'; END IF;
 PERFORM public.submit_rescheduling_request('67b4e85d-b00b-4b74-9644-99458d948c65',rid,jsonb_build_object('choice','credit','consent',true,'source','QA reversible','note','QA jersey','jersey_requested',true,'jersey_consent',true,'jersey_size',ch,'delivery','retiro'),version,gen_random_uuid());
 result:=public.admin_rescheduling_settlement_preview(rid);
 IF NOT (result->>'stale')::boolean THEN RAISE EXCEPTION 'Changed request not stale'; END IF;
 BEGIN PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',(result->'proposal'->>'version')::integer,gen_random_uuid(),'{"state":"estimated","note":"stale sources"}');RAISE EXCEPTION 'Stale sources allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Pagos o solicitud cambiaron. Recalculá' THEN RAISE;END IF;END;
 ctx:=result;version:=(ctx->'proposal'->>'version')::integer;
 BEGIN PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,gen_random_uuid(),'{"state":"validated","note":"insufficient jersey","authorized_amount":49999,"checks":{"reconciled":true,"jersey_validated":true,"stock":true,"size":true,"delivery":true}}');RAISE EXCEPTION 'Insufficient jersey allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Jersey pendiente%' THEN RAISE;END IF;END;
 BEGIN PERFORM public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,gen_random_uuid(),'{"state":"validated","note":"missing stock","authorized_amount":50000,"checks":{"reconciled":true,"jersey_validated":true,"stock":false,"size":true,"delivery":true}}');RAISE EXCEPTION 'Missing stock allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Jersey pendiente%' THEN RAISE;END IF;END;
 result:=public.admin_save_rescheduling_settlement(rid,ctx->>'source_hash',version,gen_random_uuid(),'{"state":"validated","note":"QA jersey accepted","authorized_amount":50000,"checks":{"reconciled":true,"jersey_validated":true,"stock":true,"size":true,"delivery":true}}');
 IF (result->'proposal'->>'jersey_amount')::numeric<>50000 OR (SELECT count(*) FROM public.training_camp_credit_accounts)<>0 OR (SELECT count(*) FROM public.training_camp_credit_ledger)<>0 THEN RAISE EXCEPTION 'Jersey proposal or credit lock failed';END IF;
 IF (SELECT md5(jsonb_agg(to_jsonb(r) ORDER BY id)::text) FROM public.event_reservations r) IS DISTINCT FROM before_rows THEN RAISE EXCEPTION 'Historical mutation';END IF;
 IF (SELECT public_enabled FROM public.event_rescheduling_campaigns WHERE event_id='67b4e85d-b00b-4b74-9644-99458d948c65') THEN RAISE EXCEPTION 'Public enabled';END IF;
END $$;
ROLLBACK;
